### Version

v19.2.0

### Platform

OSX 12.15.1

### Subsystem

_No response_

### What steps will reproduce the bug?

I found few cases when a Socket from node/net isn't closes when it should. Examples:

## TCP issue

If a listener .on('data') on a server socket not defined, the 'end' signal from the clients side will be ignored.

Server <a href="https://github.com/didkovsky/onend/tree/main/tcp/server.js">source</a>
``` javascript
const { createServer } = require('net')

createServer(socket => {

  socket.on('error', console.log)
  
  // Not emitted
  socket.on('end', () => console.log('end.'))
  socket.on('close', () => console.log('close.'))

  /**
   * If listener .on('data') not defined,
   * socket will ignore 'end' signal from client
   */
  // socket.on('data', () => {})

  setTimeout(() => {
    // Missing end
    // socket.end()
  }, 2000)

  setInterval(() => {
    socket.write('Data.')
  }, 500)
})
.listen(444)

```

Client <a href="https://github.com/didkovsky/onend/tree/main/tcp/client.js">source</a>
``` javascript
const { Socket } = require('net')

const socket = new Socket()
socket.on('error', console.log)

// Not emitted, if .on('data') not attached on the server side
socket.on('end', () => console.log('End.'))

// Data will come while server sends it
socket.on('data', data => console.log(data.toString('utf8')))

socket.connect({
  host: 'localhost',
  port: 444
}, () => {
  socket.write('Hello!')
 // Will be ignored
  socket.end()
})

```

## HTTP issue 1

This issue is a consequence of the TCP issue above. If we have not listener .on('data') on a req object, the 'end' signal from the clients side will be ignored.

Server <a href="https://github.com/didkovsky/onend/tree/main/http/server.js">source</a>
``` javascript
const { createServer } = require('http')

createServer((req, res) => {
  console.log('Request.')
  req.on('error', console.log)
  req.on('end', () => console.log('End.'))

  /**
   * If listener .on('data') not defined,
   * req will ignore 'end' signal from client
   */
  // req.on('data', () => {})

  const dataInt = setInterval(() => {
    res.write('Data.')
  }, 1000)

  setTimeout(() => { 
    // clearInterval(dataInt)
    // res.end('Ok.')
  }, 10000)
})
.listen(333)

```
Client <a href="https://github.com/didkovsky/onend/tree/main/http/client.js">source</a>
``` javascript
const { request } = require('http')

const options = {
  host: 'localhost',
  port: 333,
  method: 'POST',
  path: '/'
}

const req = request(options, response => {
  response.on('error', console.log)

  // Data will come while server sends it.
  response.on('data', data => console.log(data.toString('utf8')))
  // Not emitted, if .on('data') not attached on the server side
  response.on('end', () => console.log('End.'))
})

req.on('error', console.log)
req.write('Hello!')

// Will be ignored
req.end()

```

## HTTP issue 2

Server cannot close connection through res.end().

Server <a href="https://github.com/didkovsky/onend/tree/main/http-2/server.js">source</a>
``` javascript
const { createServer } = require('http')

const server = createServer((req, res) => {
  console.log('Request.')
  req.on('error', console.log)

  // Not emitted
  req.on('end', () => console.log('End.'))
  req.on('close', () => console.log('Close.'))

  req.on('data', data => {
    console.log(data.toString('utf8'))
    res.write('Ok.')

    /**
     * Will be ignored,
     * data will come while client sends it.
     */
    res.end()

    // Will close a socket.
    // res.socket.end()
    // or
    // res.destroy()
  })
})

/**
 * Also, a socket will not release.
 */
server.maxConnections = 1
server.listen(333)

```

Clien <a href="https://github.com/didkovsky/onend/tree/main/http-2/client.js">source</a>
``` javascript
const { request } = require('http')

const options = {
  host: 'localhost',
  port: 333,
  method: 'POST',
  path: '/'
}

const req = request(options, response => {
  response.on('error', console.log)
  response.on('data', data => console.log(data.toString('utf8')))

  // Not emitted
  response.on('end', () => console.log('End.'))
})

req.on('error', console.log)

setInterval(() => {
  req.write('Hello.')
}, 1000)

// Missing end
// req.end()

```

Repo with examples: https://github.com/didkovsky/onend




### How often does it reproduce? Is there a required condition?

Always

### What is the expected behavior?

If I call socket.end() I expect to get 'end' event. And stop receiving data on .on('data') listener.

### What do you see instead?

If we have not .on('data') listener, socket ignore 'end' signal.
 
